  Lemma r10_step (cin : Z) : 0 <= cin <= 10 ->
    let S := (r10_L + cin) mod 2 ^ 64 in
    S + 2 ^ 64 * (r10_c + r10_A + (if S <? r10_L then 1 else 0)) = 10 * x + cin /\ 0 <= S < 2 ^ 64.
Proof.
