(* [comment removed for export] *)
Lemma r10_two (x0 x1 : Z) : 0 <= x0 < 2 ^ 64 -> 0 <= x1 < 2 ^ 64 ->
  let S := (r10_c x0 + ((r10_T x1 + ((r10_A x0 + r10_B x1) mod 2 ^ 64)) mod 2 ^ 64)) mod 2 ^ 64 in
  let C := ((if S <? r10_L x1 then 1 else 0) + ((r10_c x1 + r10_A x1) mod 2 ^ 64)) mod 2 ^ 64 in
  r10_L x0 + 2 ^ 64 * S + 2 ^ 128 * C = 10 * (x0 + 2 ^ 64 * x1) /\ 0 <= r10_L x0 < 2 ^ 64 /\ 0 <= S < 2 ^ 64 /\ 0 <= C <= 10.
Proof.
