Section ZSkip.
  Variables (fx : FPState) (M : word -> option byte) (c0 e : Z).
  (* [comment removed for export] *)
  Variable tb : Z -> Z.
  Hypothesis TB : forall i, 0 <= i -> c0 + i < e -> L5.u8_at RSEGS M (c0 + i) (tb i) /\ 0 <= tb i < 256.
  Hypothesis RC : 0 <= c0 /\ c0 < e /\ e <= 2 ^ 47.

  Abbreviation st R pc := (@mkst fx R (Z_to_bv 64 pc) M (seg_rom RSEGS)).
  Definition zregs (R R' : bvmap 5 word) : Prop := forall x : nat, (x < 32)%nat -> x <> 10%nat -> x <> 12%nat -> getr R' (reg x) = getr R (reg x).

  Lemma zregs_refl R : zregs R R.
Proof.
