  (* [comment removed for export] *)
  Lemma zstep R (i : Z) :
    getr R (reg 10) = Z_to_bv 64 (c0 + i) -> getr R (reg 11) = Z_to_bv 64 48 -> getr R (reg 8) = Z_to_bv 64 e -> 0 <= i -> c0 + i < e ->
    exists R', zregs R R' /\ getr R' (reg 11) = Z_to_bv 64 48 /\ getr R' (reg 8) = Z_to_bv 64 e /\
      (  (tb i = 48 /\ c0 + i + 1 < e /\ msteps RSEGS (st R 0x42f74) (st R' 0x42f74) /\ getr R' (reg 10) = Z_to_bv 64 (c0 + i + 1))
      \/ (tb i = 48 /\ c0 + i + 1 = e /\ msteps RSEGS (st R 0x42f74) (st R' 0x42f98) /\ getr R' (reg 10) = Z_to_bv 64 e)
      \/ (tb i <> 48 /\ msteps RSEGS (st R 0x42f74) (st R' 0x42f88) /\ getr R' (reg 10) = Z_to_bv 64 (c0 + i))).
Proof.
