  (* [comment removed for export] *)
  Lemma zskip R :
    getr R (reg 10) = Z_to_bv 64 c0 -> getr R (reg 11) = Z_to_bv 64 48 -> getr R (reg 8) = Z_to_bv 64 e ->
    exists R' (z : Z), zregs R R' /\ 0 <= z /\ (forall i, 0 <= i < z -> tb i = 48) /\
      (  (c0 + z = e /\ msteps RSEGS (st R 0x42f74) (st R' 0x42f98))
      \/ (c0 + z < e /\ tb z <> 48 /\ msteps RSEGS (st R 0x42f74) (st R' 0x42f88) /\ getr R' (reg 10) = Z_to_bv 64 (c0 + z))).
Proof.
