Lemma grow (E rr v0 v1 : Z) (fx1 : FPState) (R1 : bvmap 5 word) (M1 : word -> option byte) (model1 : Model) :
  mem_ok M1 -> hi_heap HI LB cr0 M1 (m_vmmaps model1) -> model_but_vm model0 model1 ->
  (E = sp - 160 \/ E = sp - 208) -> L5.ra_ok rr ->
  getr R1 (reg 1) = Z_to_bv 64 rr -> getr R1 (reg 2) = Z_to_bv 64 E -> getr R1 (reg 10) = Z_to_bv 64 (sp - 112) -> getr R1 (reg 11) = Z_to_bv 64 3 ->
  getr R1 (reg 4) = Z_to_bv 64 (pa_tp AD) ->
  L5.u8_at RSEGS M1 (sp - 112) 0 -> L5.u64_at RSEGS M1 (sp - 112 + 8) 2 -> L5.u64_at RSEGS M1 (sp - 112 + 16) v0 -> L5.u64_at RSEGS M1 (sp - 112 + 24) v1 ->
  0 <= v0 < 2 ^ 64 -> 0 <= v1 < 2 ^ 64 ->
  (forall (fx3 : FPState) (R3 : bvmap 5 word) (M3 : word -> option byte) (model3 : Model) (p : Z),
      mem_ok M3 -> hi_heap HI ((p, 64) :: LB) (debitR cr0 64) M3 (m_vmmaps model3) -> model_but_vm model0 model3 ->
      getr R3 (reg 2) = Z_to_bv 64 E -> getr R3 (reg 10) = Z_to_bv 64 (p + 16) ->
      (forall i, In i [8; 9; 18; 19; 20; 21]%nat -> getr R3 (reg i) = getr R1 (reg i)) ->
      (forall i, In i [3; 4; 22; 23; 24; 25; 26; 27]%nat -> getr R3 (reg i) = getr R1 (reg i)) ->
      L5.u8_at RSEGS M3 (sp - 112) 1 /\ L5.u64_at RSEGS M3 (sp - 112 + 8) 3 /\ L5.u64_at RSEGS M3 (sp - 112 + 16) 8 /\ L5.u64_at RSEGS M3 (sp - 112 + 24) p ->
      L5.u64_at RSEGS M3 p v0 /\ L5.u64_at RSEGS M3 (p + 8) v1 /\ L5.u64_at RSEGS M3 (p + 16) 0 /\ L5.defined M3 p 64 ->
      L5C.fresh_block L LB M3 p 64 -> p mod 16 = 0 -> 4096 <= p -> p + 64 <= hl_ceil L ->
      (forall a m, E <= a -> a + m <= 2 ^ 47 -> (a + m <= sp - 112 \/ sp - 112 + 32 <= a) -> L5C.agree_on M1 M3 a m) ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx3 R3 rr M3 model3) K) ->
