(* [comment removed for export] *)
Definition xfin (M : word -> option byte) (fb : Z) (len : nat) (v0 v1 : Z) : Prop :=
  PQTSS.binl_at M o fb len v0 v1 /\ (len <= 2)%nat /\ len = PQTSS.wlen v0 v1 /\ (fb = 0 \/ fb = 2).
Lemma xfin_cells M fb len v0 v1 : (fb = 0 \/ fb = 2) -> L5.u8_at RSEGS M o fb -> L5.u64_at RSEGS M (o + 8) (Z.of_nat len) ->
  L5.u64_at RSEGS M (o + 16) v0 -> L5.u64_at RSEGS M (o + 24) v1 -> 0 <= v0 < 2 ^ 64 -> 0 <= v1 < 2 ^ 64 ->
  (len = 0%nat /\ v0 = 0 /\ v1 = 0) \/ (len = 1%nat /\ 1 <= v0 /\ v1 = 0) \/ (len = 2%nat /\ 1 <= v1) -> xfin M fb len v0 v1.
Proof.
