(* [comment removed for export] *)
Lemma tail_dyn (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (ec fl e' p fb v0 v1 : Z) (len : nat) :
  mem_ok M -> hi_heap HI ((p, 64) :: LB) (debitR cr0 64) M (m_vmmaps model) -> model_but_vm model0 model -> saved M -> CSV R ->
  getr R (reg 2) = Z_to_bv 64 (sp - 112) -> getr R (reg 8) = Z_to_bv 64 e' -> 0 <= e' < 2 ^ 64 -> getr R (reg 9) = Z_to_bv 64 ec -> (ec = 0 \/ ec = 22) ->
  getr R (reg 21) = Z_to_bv 64 9 ->
  L5.u8_at RSEGS M (sp - 112) fl -> 0 <= fl < 256 -> Z.testbit fl 0 = true -> L5.u64_at RSEGS M (sp - 112 + 16) 8 -> L5.u64_at RSEGS M (sp - 112 + 24) p ->
  4096 <= p -> p + 64 <= hl_ceil L -> xfin M fb len v0 v1 ->
