Lemma exit_D (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (neg e' p v0 v1 : Z) :
  mem_ok M -> hi_heap HI ((p, 64) :: LB) (debitR cr0 64) M (m_vmmaps model) -> model_but_vm model0 model -> saved M -> xz M -> CSV R ->
  getr R (reg 2) = Z_to_bv 64 (sp - 112) -> getr R (reg 8) = Z_to_bv 64 e' -> 0 <= e' < 2 ^ 64 -> getr R (reg 9) = Z_to_bv 64 o ->
  getr R (reg 19) = Z_to_bv 64 neg -> (neg = 0 \/ neg = 1) -> getr R (reg 20) = Z_to_bv 64 0 -> getr R (reg 21) = Z_to_bv 64 9 ->
  L5.u8_at RSEGS M (sp - 112) 1 -> L5.u64_at RSEGS M (sp - 112 + 8) 2 -> L5.u64_at RSEGS M (sp - 112 + 16) 8 -> L5.u64_at RSEGS M (sp - 112 + 24) p ->
  L5.u64_at RSEGS M p v0 -> L5.u64_at RSEGS M (p + 8) v1 -> L5.defined M p 64 -> 0 <= v0 < 2 ^ 64 -> 1 <= v1 < 2 ^ 62 -> p mod 16 = 0 -> 4096 <= p -> p + 64 <= hl_ceil L ->
