Inductive shp : Type := SI0 | SI1 (v0 : Z) | SI2 (v0 v1 : Z) | SDY (p v0 v1 : Z).
Definition tval (sh : shp) : Z := match sh with SI0 => 0 | SI1 v0 => v0 | SI2 v0 v1 => v0 + 2 ^ 64 * v1 | SDY _ v0 v1 => v0 + 2 ^ 64 * v1 end.
Definition theap (sh : shp) (M : word -> option byte) (model : Model) : Prop :=
  match sh with SDY p _ _ => hi_heap HI ((p, 64) :: LB) (debitR cr0 64) M (m_vmmaps model) | _ => hi_heap HI LB cr0 M (m_vmmaps model) end.
Definition tmp_at (M : word -> option byte) (sh : shp) : Prop :=
  match sh with
  | SI0 => L5.u8_at RSEGS M (sp - 112) 0 /\ L5.u64_at RSEGS M (sp - 112 + 8) 0 /\ L5.u64_at RSEGS M (sp - 112 + 16) 0 /\ L5.u64_at RSEGS M (sp - 112 + 24) 0
  | SI1 v0 => L5.u8_at RSEGS M (sp - 112) 0 /\ L5.u64_at RSEGS M (sp - 112 + 8) 1 /\ L5.u64_at RSEGS M (sp - 112 + 16) v0 /\ L5.u64_at RSEGS M (sp - 112 + 24) 0 /\ 1 <= v0 < 2 ^ 64
  | SI2 v0 v1 => L5.u8_at RSEGS M (sp - 112) 0 /\ L5.u64_at RSEGS M (sp - 112 + 8) 2 /\ L5.u64_at RSEGS M (sp - 112 + 16) v0 /\ L5.u64_at RSEGS M (sp - 112 + 24) v1
                  /\ 0 <= v0 < 2 ^ 64 /\ 1 <= v1 < 2 ^ 64
  | SDY p v0 v1 => L5.u8_at RSEGS M (sp - 112) 1 /\ L5.u64_at RSEGS M (sp - 112 + 8) 2 /\ L5.u64_at RSEGS M (sp - 112 + 16) 8 /\ L5.u64_at RSEGS M (sp - 112 + 24) p
                  /\ L5.u64_at RSEGS M p v0 /\ L5.u64_at RSEGS M (p + 8) v1 /\ L5.defined M p 64 /\ 0 <= v0 < 2 ^ 64 /\ 1 <= v1 < 2 ^ 64
                  /\ p mod 16 = 0 /\ 4096 <= p /\ p + 64 <= hl_ceil L /\ HeapIface.blocks_apart p 64 LB
  end.
Lemma tval_nonneg M sh : tmp_at M sh -> 0 <= tval sh.
Proof.
