(* [comment removed for export] *)
Definition hregs (R : bvmap 5 word) (c neg m : Z) : Prop :=
  getr R (reg 2) = Z_to_bv 64 (sp - 112) /\ getr R (reg 8) = Z_to_bv 64 (s + n) /\ getr R (reg 9) = Z_to_bv 64 o /\ getr R (reg 18) = Z_to_bv 64 c
  /\ getr R (reg 19) = Z_to_bv 64 neg /\ getr R (reg 20) = Z_to_bv 64 m /\ getr R (reg 21) = Z_to_bv 64 9.

Local Ltac bfeed P WR SD := PMK.feed P ltac:(first [gfeed | (apply (L5.writable_sub RSEGS _ (sp - 9216) 9216); [exact WR|lia|lia]) | (apply (L5.defined_sub _ (sp - 9216) 9216); [exact SD|lia|lia])
    | (lazymatch goal with |- L5.writable _ ?Mx ?px 64 => apply (L5C.writable_of_defined RSEGS Mx px 64); [assumption| lia| lia] end)
    | (lazymatch goal with |- L5.defined ?Mx (?px + ?k) ?w => apply (L5.defined_sub Mx px 64); [assumption| lia| lia] end) ]).

