(* [comment removed for export] *)
Lemma mtail (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (p v0 v1 c neg m b : Z) :
  mem_ok M -> hi_heap HI ((p, 64) :: LB) (debitR cr0 64) M (m_vmmaps model) -> model_but_vm model0 model -> saved M -> xz M -> CSV R ->
  getr R (reg 2) = Z_to_bv 64 (sp - 112 - 48) -> getr R (reg 8) = Z_to_bv 64 (sp - 112) -> getr R (reg 9) = Z_to_bv 64 10 -> getr R (reg 19) = Z_to_bv 64 v0 ->
  getr R (reg 20) = Z_to_bv 64 2 -> getr R (reg 21) = Z_to_bv 64 9 -> getr R (reg 22) = Z_to_bv 64 b ->
  L5.u8_at RSEGS M (sp - 112) 1 -> L5.u64_at RSEGS M (sp - 112 + 8) 3 -> L5.u64_at RSEGS M (sp - 112 + 16) 8 -> L5.u64_at RSEGS M (sp - 112 + 24) p ->
  L5.u64_at RSEGS M p v0 -> L5.u64_at RSEGS M (p + 8) v1 -> L5.u64_at RSEGS M (p + 16) 0 -> L5.defined M p 64 ->
  0 <= v0 < 2 ^ 64 -> 1 <= v1 -> v0 + 2 ^ 64 * v1 < 10 ^ 30 -> p mod 16 = 0 -> 4096 <= p -> p + 64 <= hl_ceil L -> HeapIface.blocks_apart p 64 LB ->
  L5.u64_at RSEGS M (sp - 112 - 8) 0x43030 -> L5.u64_at RSEGS M (sp - 112 - 16) (s + n) -> L5.u64_at RSEGS M (sp - 112 - 24) o -> L5.u64_at RSEGS M (sp - 112 - 32) c ->
  L5.u64_at RSEGS M (sp - 112 - 40) neg -> L5.u64_at RSEGS M (sp - 112 - 48) m -> 1 <= c < 2 ^ 47 -> (neg = 0 \/ neg = 1) -> 1 <= m <= 31 -> 48 <= b <= 57 ->
  (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (w0 w1 : Z),
      mem_ok M' -> hi_heap HI ((p, 64) :: LB) (debitR cr0 64) M' (m_vmmaps model) -> saved M' -> xz M' -> CSV R' ->
      hregs R' c neg m -> getr R' (reg 22) = Z_to_bv 64 b -> tmp_at M' (SDY p w0 w1) -> w0 + 2 ^ 64 * w1 = 10 * (v0 + 2 ^ 64 * v1) ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' 0x43030 M' model) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx R 0x43164 M model) K.
