(* [comment removed for export] *)
Definition VH (c v0 v1 p neg m b : Z) (R : bvmap 5 word) : nat -> Z := fun j : nat => match j with 2%nat => sp - 112 | 34%nat => o | 35%nat => c | 36%nat => v0 | 38%nat => v1 | 41%nat => p | 42%nat => s + n
             | 43%nat => neg | 44%nat => m | 45%nat => b | 47%nat => bv_unsigned (getr R (reg 22))
             | 48%nat => bv_unsigned (getr R (reg 1)) | 49%nat => bv_unsigned (getr R (reg 10)) | 50%nat => bv_unsigned (getr R (reg 11)) | 51%nat => bv_unsigned (getr R (reg 12))
             | 52%nat => bv_unsigned (getr R (reg 13)) | 53%nat => bv_unsigned (getr R (reg 14)) | 54%nat => bv_unsigned (getr R (reg 15)) | 55%nat => bv_unsigned (getr R (reg 16))
             | 56%nat => bv_unsigned (getr R (reg 17)) | 57%nat => bv_unsigned (getr R (reg 5)) | 58%nat => bv_unsigned (getr R (reg 6)) | 59%nat => bv_unsigned (getr R (reg 7))
             | 60%nat => bv_unsigned (getr R (reg 28)) | 61%nat => bv_unsigned (getr R (reg 29)) | 62%nat => bv_unsigned (getr R (reg 30)) | 63%nat => bv_unsigned (getr R (reg 31)) | _ => 0 end.

(* [comment removed for export] *)
Lemma keep_win M M2 (pb : Z) : saved M -> xz M ->
  (forall i, 0 <= i < 2 ^ 64 -> ~ (sp - 112 - 400 <= i < sp - 112 - 400 + 432) -> ~ (pb + 0 <= i < pb + 0 + 64) -> M2 (Z_to_bv 64 i) = M (Z_to_bv 64 i)) ->
  pb + 64 <= hl_ceil L -> saved M2 /\ xz M2.
Proof.
