(* [comment removed for export] *)
Lemma mul_ok (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (sh : shp) (c neg m i : Z) :
  mem_ok M -> theap sh M model -> model_but_vm model0 model -> saved M -> xz M -> CSV R -> hregs R c neg m -> (neg = 0 \/ neg = 1) -> 1 <= m <= 31 ->
  c = s + i -> 0 <= i < n -> 48 <= tb i <= 57 -> tmp_at M sh -> tval sh < 10 ^ 30 ->
  (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (sh' : shp),
      mem_ok M' -> theap sh' M' model' -> model_but_vm model0 model' -> saved M' -> xz M' -> CSV R' ->
      hregs R' c neg m -> getr R' (reg 22) = Z_to_bv 64 (tb i) -> tmp_at M' sh' -> tval sh' = 10 * tval sh ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' 0x43030 M' model') K) ->
